-- public.stones_refusal(p_world uuid, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.stones_refusal(p_world uuid, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_t int; v_kind text;
begin
  if not in_bounds(p_world, p_x, p_y) then return 'There is nothing there.'; end if;
  if under_building(p_world, p_x, p_y) is not null then return under_building(p_world, p_x, p_y); end if;
  if (slab_at(p_world, p_x, p_y)).id is not null then
    return 'Not on a poured slab.';
  end if;
  v_t := land_tile(p_world, p_x, p_y);
  if v_t = tile_id('Stepping stones') then return 'Stepping stones already here.'; end if;
  if not has_water(p_world, p_x, p_y) and not water_runs(p_world, p_x, p_y) then
    return 'Stepping stones go in water: sea edge, pond or stream.';
  end if;
  if water_depth(p_world, p_x, p_y) > stones_depth() then
    return 'Too deep: stepping stones need water '
        || metres(stones_depth()) || ' m deep or less.';
  end if;
  if not exists (select 1 from stone_bed b where b.tile = v_t) then
    return 'Stepping stones need bare ground or flat growth: clear the tile first.';
  end if;
  select w.kind into v_kind from water_plant w where w.world_id = p_world and w.x = p_x and w.y = p_y;
  if v_kind is not null then return 'Pull up the ' || water_plant_word(v_kind) || ' first.'; end if;
  return null;
end $function$
